Definition T3 : (word -> option byte) -> Z -> Z -> Prop := fun _ _ _ => True.
Definition T4 : (word -> option byte) -> Z -> Z -> Z -> Prop := fun _ _ _ _ => True.
Abbreviation vstr_at := (PM.vstr_at segs T3).
Abbreviation vec_at := (PM.vec_at segs T3 T4).
Abbreviation iss_at := (PM.iss_at segs A T3).
Abbreviation nullis_at := (PM.nullis_at segs A T3).
Abbreviation parser_at := (PM.parser_at segs A T3 T4).
Abbreviation src_fields_at := (PM.src_fields_at segs T3).
Abbreviation loc_ok := (PMST.loc_ok segs A).
Abbreviation sys_ok := (PMST.sys_ok segs A).
Abbreviation err_ok := (PMST.err_ok segs A).

Definition cfg {fx : FPState} (R : bvmap 5 word) (pc : Z) (M : word -> option byte) (model : Model) : config :=
  mkCfg (@mkst fx R (Z_to_bv 64 pc) M (seg_rom segs)) model.
Definition model_ok (model : Model) : Prop :=
  m_halted model = None /\ m_vm_lazy model = [] /\ m_vm_materialized model = [].

(* [comment removed for export] *)
Definition pm_scr (h : Z) : Z := 12288 + 2048 * h.
(* [comment removed for export] *)
Definition entry (R : bvmap 5 word) (M : word -> option byte) (sp r h : Z) : Prop :=
  getr R 1%bv = Z_to_bv 64 r /\ L5.ra_ok r /\ getr R 2%bv = Z_to_bv 64 sp /\ getr R 3%bv = Z_to_bv 64 (pa_gp A)
  /\ getr R 4%bv = Z_to_bv 64 (pa_tp A) /\ L5C.stk (hl_sptop L) M sp (pm_scr h).
(* [comment removed for export] *)
Definition frame_ok (sp fb : Z) : Prop := sp <= fb /\ fb + pa_frame A <= hl_sptop L /\ fb mod 16 = 0.
Definition o_ec (fb : Z) : Z := fb + pa_off_ec A.
Definition o_p (fb : Z) : Z := fb + pa_off_p A.
Definition o_v (fb : Z) : Z := fb + pa_off_v A.
Definition o_is (fb : Z) : Z := fb + pa_off_is A.
Definition o_s (fb : Z) : Z := fb + pa_off_s A.
Definition o_src (fb : Z) : Z := o_p fb + 24.
Definition o_tb (fb : Z) : Z := o_p fb + 336.
Definition o_vec (fb : Z) : Z := o_p fb + 360.

(* [comment removed for export] *)
Definition credit_le (c c' : credit) : Prop := fst c <= fst c' /\ snd c <= snd c'.
Definition credit_keep (cr cr' p p' : credit) : Prop :=
  fst cr - fst p + fst p' <= fst cr' /\ snd cr - snd p + snd p' <= snd cr'.
Definition cr0 : credit := (0, 0).

(* [comment removed for export] *)
Definition ec_at (M : word -> option byte) (o v c : Z) : Prop := L5.u32_at segs M o v /\ L5.u64_at segs M (o + 8) c /\ L5.defined M o 16.
(* [comment removed for export] *)
Definition visitor_at (M : word -> option byte) (o : Z) : Prop := L5.u64_at segs M o (pa_vp_visitor A).

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition OPNEW_SCR : Z := 16 + 8224.
Definition OPDEL_SCR : Z := 8224.

Definition opnew_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (cr : credit) (n sp r : Z),
    hi_heap HI LB cr M (m_vmmaps model) -> model_ok model -> K [] ->
    getr R 10%bv = Z_to_bv 64 n -> 0 < n <= 2 ^ 27 -> credit_ok L cr n ->
    getr R 1%bv = Z_to_bv 64 r -> L5.ra_ok r ->
    getr R 2%bv = Z_to_bv 64 sp -> getr R 4%bv = Z_to_bv 64 (pa_tp A) -> L5C.stk (hl_sptop L) M sp OPNEW_SCR ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (B : Z),
        getr R' 10%bv = Z_to_bv 64 B -> regs_preserved R R' ->
        L5C.fresh_block L LB M' B n ->
        L5C.hpres L LB sp OPNEW_SCR [] M M' ->
        model_but_vm model model' -> hi_heap HI ((B, n) :: LB) (debit L cr n) M' (m_vmmaps model') ->
        srealizes segs SCFG (cfg R' r M' model') K) ->
    srealizes segs SCFG (cfg R (pa_opnew A) M model) K.

Definition opdel_spec_at (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (cr : credit) (B n sp r : Z),
    hi_heap HI LB cr M (m_vmmaps model) -> model_ok model -> K [] ->
    In (B, n) LB -> getr R 10%bv = Z_to_bv 64 B ->
    getr R 1%bv = Z_to_bv 64 r -> L5.ra_ok r ->
    getr R 2%bv = Z_to_bv 64 sp -> getr R 4%bv = Z_to_bv 64 (pa_tp A) -> L5C.stk (hl_sptop L) M sp OPDEL_SCR ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model),
        regs_preserved R R' ->
        L5C.hpres L (lb_remove B LB) sp OPDEL_SCR [] M M' ->
        model_but_vm model model' -> hi_heap HI (lb_remove B LB) cr M' (m_vmmaps model') ->
        srealizes segs SCFG (cfg R' r M' model') K) ->
    srealizes segs SCFG (cfg R pc M model) K.
Definition opdel_spec : Prop := opdel_spec_at (pa_opdel A).
Definition opdel_sized_spec : Prop := opdel_spec_at (pa_opdel_sized A).

