Definition parser_init (qc b : Z) : PM.pst :=
  PM.PST 1 0 0 (PM.SRC qc qc 0) (PM.VShort 0) 0 b 0 [PM.ps_root].
Definition reader_ctor_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (cr : credit) (sp r fb oo oa : Z) (str : PM.vstr) (sm : PM.strm),
    hi_heap HI LB cr M (m_vmmaps model) -> model_ok model -> K [] -> entry R M sp r 6 -> frame_ok sp fb ->
    getr R 10%bv = Z_to_bv 64 (o_p fb) -> getr R 11%bv = Z_to_bv 64 (o_is fb) -> getr R 12%bv = Z_to_bv 64 oo -> getr R 13%bv = Z_to_bv 64 oa ->
    fb <= oo -> oo + 32 <= o_p fb -> oo mod 8 = 0 -> L5.defined M (o_p fb) 384 -> L5.u64_at segs M oo (pa_vp_opts A) -> L5.u64_at segs M (oo + 8) PM.MAX_ITEMS -> L5.u32_at segs M (oo + 24) PM.MAX_DEPTH ->
    iss_at M (o_is fb) str sm -> PMST.base_ok segs A M -> loc_ok M true ->
    credit_le (PM.credit_add (PM.cost1 L PM.CHUNK) (PM.cost1 L 32)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (qc b : Z) (cr' : credit),
        regs_preserved R R' -> parser_at M' (o_p fb) (o_is fb) (parser_init qc b) ->
        L5C.hpres L LB sp (pm_scr 6) [(o_p fb, 384)] M M' ->
        credit_keep cr cr' (PM.credit_add (PM.cost1 L PM.CHUNK) (PM.cost1 L 32)) cr0 ->
        model_but_vm model model' -> hi_heap HI (PM.parser_own (parser_init qc b) ++ LB) cr' M' (m_vmmaps model') ->
        srealizes segs SCFG (cfg R' r M' model') K) ->
    srealizes segs SCFG (cfg R (pa_reader_ctor A) M model) K.

