    getr R 10%bv = Z_to_bv 64 p -> getr R 11%bv = Z_to_bv 64 n -> 0 <= n < 2 ^ 26 -> 0 <= p -> (n = 0 \/ 0 < p) -> p + n <= 2 ^ 47 -> L5.defined M p n ->
    (n = 0 \/ sp <= p \/ p + n <= sp - pm_scr 0) ->
