        ((ptr = 0 /\ n = 0) \/ in_blk (PM.src_own src' ++ PM.vs_own tb' ++ OB) ptr n \/ (tw_otb T + 1 <= ptr /\ ptr + n <= tw_otb T + 24)) ->
