From OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib Require PropExec. Require OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0038. Require OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0030. Require OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0036. Require OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0084. Require OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0018. Import OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.PropExec OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0038.CatExec OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0030.CatSim OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0038.StoreOk OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0038.Hoare OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0036.ShapeAlg OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0036.SpinAlg OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0084.HeapIface OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0084.L5Defs OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0090.L5Core OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0018.PmLayout OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0090.PmModel OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0090.PmStatics OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0090.PmSpecs.
From OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib Require Import BMode.
Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module WD.

(* [comment removed for export] *)
Definition WD_SCR : Z := 16384.          (* [comment removed for export] *)
Definition PB_SCR : Z := 14336.          (* [comment removed for export] *)
Definition WD_MAX : Z := 32.
Definition STR_MAX : Z := 2 ^ 30.

Section Wd.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable segs : list Segment.
Variable A : pm_addrs.
Variable L : heap_layout.
Variable HI : heap_iface.
(* [comment removed for export] *)
Variable sst : Type.
Variable str_at : (word -> option byte) -> Z -> sst -> Prop.
Variable str_own : sst -> list (Z * Z).
Variable str_size : sst -> Z.
Variable str_pot : sst -> credit.

(* [comment removed for export] *)
Definition entry_scr (R : bvmap 5 word) (M : word -> option byte) (sp r scr : Z) : Prop :=
  getr R 1%bv = Z_to_bv 64 r /\ L5.ra_ok r /\ getr R 2%bv = Z_to_bv 64 sp /\ getr R 3%bv = Z_to_bv 64 (pa_gp A)
  /\ getr R 4%bv = Z_to_bv 64 (pa_tp A) /\ L5C.stk (hl_sptop L) M sp scr.

(* [comment removed for export] *)
Definition wd_at (M : word -> option byte) (o : Z) : Prop :=
  L5.u8_at segs M o 0 /\ L5.u32_at segs M (o + 4) 0 /\ L5.defined M o 12.

(* [comment removed for export] *)
Definition apart24 (p n os : Z) : Prop := p + n <= os \/ os + 24 <= p.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition push_back_spec (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (cr : credit) (os c sp r : Z) (x : sst),
    hi_heap HI (str_own x ++ LBX) cr M (m_vmmaps model) -> PMSP.model_ok model -> K [] ->
    entry_scr R M sp r PB_SCR ->
    getr R 10%bv = Z_to_bv 64 os -> getr R 11%bv = Z_to_bv 64 c -> 0 <= c < 256 ->
    str_at M os x -> str_size x < STR_MAX -> sp <= os -> os + 24 <= hl_sptop L ->
    PMST.base_ok segs A M -> PMSP.credit_le (str_pot x) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (x' : sst) (cr' : credit),
        regs_preserved R R' -> str_at M' os x' -> str_size x' = str_size x + 1 ->
        L5C.hpres L LBX sp PB_SCR [(os, 24)] M M' -> PMSP.credit_keep cr cr' (str_pot x) (str_pot x') ->
        model_but_vm model model' -> hi_heap HI (str_own x' ++ LBX) cr' M' (m_vmmaps model') ->
        srealizes segs SCFG (@PMSP.cfg segs fx' R' r M' model') K) ->
    srealizes segs SCFG (@PMSP.cfg segs fx R pc M model) K.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition wd_spec (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (cr : credit) (o so os sp r : Z) (x : sst),
    hi_heap HI (str_own x ++ LBX) cr M (m_vmmaps model) -> PMSP.model_ok model -> K [] ->
    entry_scr R M sp r WD_SCR ->
    getr R 10%bv = Z_to_bv 64 o -> getr R 11%bv = Z_to_bv 64 so ->
    wd_at M o -> L5.u64_at segs M so os -> str_at M os x -> str_size x + WD_MAX <= STR_MAX ->
    sp <= o -> o + 12 <= hl_sptop L -> sp <= so -> so + 8 <= hl_sptop L -> sp <= os -> os + 24 <= hl_sptop L ->
    apart24 o 12 os -> apart24 so 8 os ->
    PMST.base_ok segs A M -> PMSP.credit_le (str_pot x) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (x' : sst) (cr' : credit),
        regs_preserved R R' -> str_at M' os x' -> str_size x <= str_size x' <= str_size x + WD_MAX ->
        L5C.hpres L LBX sp WD_SCR [(os, 24)] M M' -> PMSP.credit_keep cr cr' (str_pot x) (str_pot x') ->
        model_but_vm model model' -> hi_heap HI (str_own x' ++ LBX) cr' M' (m_vmmaps model') ->
        srealizes segs SCFG (@PMSP.cfg segs fx' R' r M' model') K) ->
    srealizes segs SCFG (@PMSP.cfg segs fx R pc M model) K.

End Wd.
End WD.

End WdSpec.
