(* [comment removed for export] *)
(* [comment removed for export] *)
Definition credit_le (c c' : credit) : Prop := fst c <= fst c' /\ snd c <= snd c'.

(* [comment removed for export] *)
Lemma pot_text_step L s s' tg :
  2 * PM.vs_cap s <= PM.vs_cap s' ->
